'use strict';
/* Post-generation validation. Operates on the real generated bytes — it
   re-parses the safetensors buffer, recomputes the expected shapes and the
   analytic parameter count, and checks the tokenizer round-trip. The same
   checks exist as validate.py so local and CI validation agree. */

const spec = require('./model-spec');
const corpus = require('./corpus');

function expectedShapes(cfg) {
  const d = cfg.d_model;
  const V = cfg.vocab_size;
  const ctx = cfg.n_ctx;
  const ff = cfg.d_ff;
  const L = cfg.n_layer;
  const shapes = {
    'model.tok_emb.weight': [V, d],
    'model.pos_emb.weight': [ctx, d],
    'model.ln_f.weight': [d],
    'model.ln_f.bias': [d],
  };
  if (!cfg.tie_word_embeddings) shapes['lm_head.weight'] = [V, d];
  for (let i = 0; i < L; i++) {
    shapes[`model.blocks.${i}.ln_1.weight`] = [d];
    shapes[`model.blocks.${i}.ln_1.bias`] = [d];
    shapes[`model.blocks.${i}.ln_2.weight`] = [d];
    shapes[`model.blocks.${i}.ln_2.bias`] = [d];
    shapes[`model.blocks.${i}.attn.c_attn.weight`] = [3 * d, d];
    shapes[`model.blocks.${i}.attn.c_attn.bias`] = [3 * d];
    shapes[`model.blocks.${i}.attn.c_proj.weight`] = [d, d];
    shapes[`model.blocks.${i}.attn.c_proj.bias`] = [d];
    shapes[`model.blocks.${i}.mlp.fc_in.weight`] = [ff, d];
    shapes[`model.blocks.${i}.mlp.fc_in.bias`] = [ff];
    shapes[`model.blocks.${i}.mlp.fc_out.weight`] = [d, ff];
    shapes[`model.blocks.{i}.mlp.fc_out.bias`.replace('{i}', i)] = [d];
  }
  return shapes;
}

function floatView(buf, count) {
  // safetensors payloads are little-endian float32
  const out = new Float32Array(count);
  for (let i = 0; i < count; i++) out[i] = buf.readFloatLE(i * 4);
  return out;
}

function validateProject(project) {
  const checks = [];
  const add = (id, label, ok, detail) => checks.push({ id, label, status: ok ? 'pass' : 'fail', detail });
  const cfg = project.config;
  const counts = cfg.parameter_breakdown;

  // --- architecture -----------------------------------------------------
  add('arch.divisibility', 'd_model divisible by n_head', cfg.d_model % cfg.n_head === 0,
    `${cfg.d_model} / ${cfg.n_head} = ${cfg.d_model / cfg.n_head}`);
  add('arch.budget', 'Parameter count within 2% of target',
    Math.abs(project.parameters - project.configJson.target_parameters) / project.configJson.target_parameters <= 0.02,
    `${project.parameters.toLocaleString()} vs target ${project.configJson.target_parameters.toLocaleString()} (${cfg.deviation.toFixed(3)}%)`);
  add('arch.depth', 'Layer depth in supported range', cfg.n_layer >= 2 && cfg.n_layer <= 48, `${cfg.n_layer} blocks`);
  add('arch.ctx', 'Context window valid', cfg.n_ctx >= 64 && cfg.n_ctx <= 4096, `${cfg.n_ctx} tokens`);

  // --- safetensors ------------------------------------------------------
  const weightsFile = project.files.find((f) => f.path === 'weights/model.safetensors');
  if (!weightsFile) {
    add('weights.present', 'Weight file present', false, 'weights/model.safetensors missing');
    return finish(project, checks);
  }
  let parsed;
  try {
    parsed = spec.readSafetensors(weightsFile.content);
    add('weights.parse', 'safetensors header parses', true, `${parsed.tensors.size} tensors, metadata keys: ${Object.keys(parsed.metadata).length}`);
  } catch (err) {
    add('weights.parse', 'safetensors header parses', false, err.message);
    return finish(project, checks);
  }

  const shapes = expectedShapes(cfg);
  const missing = Object.keys(shapes).filter((k) => !parsed.tensors.has(k));
  const extra = [...parsed.tensors.keys()].filter((k) => !shapes[k]);
  add('weights.complete', 'Every expected tensor present', missing.length === 0,
    missing.length ? `missing ${missing.length}: ${missing.slice(0, 3).join(', ')}` : `all ${Object.keys(shapes).length} expected tensors present`);
  add('weights.no_extra', 'No unexpected tensors', extra.length === 0,
    extra.length ? `unexpected: ${extra.slice(0, 3).join(', ')}` : 'manifest matches architecture exactly');

  let shapeErrors = [];
  let elementTotal = 0;
  let nonFinite = 0;
  let degenerate = 0;
  let lnBad = 0;
  let biasBad = 0;
  for (const [name, tensor] of parsed.tensors) {
    const expected = shapes[name];
    if (expected && JSON.stringify(expected) !== JSON.stringify(tensor.shape)) {
      shapeErrors.push(`${name}: expected ${expected}, got ${tensor.shape}`);
    }
    const elements = tensor.shape.reduce((a, b) => a * b, 1);
    elementTotal += elements;
    if (tensor.dtype !== 'F32') shapeErrors.push(`${name}: dtype ${tensor.dtype}`);
    if (tensor.data.length !== elements * 4) shapeErrors.push(`${name}: byte length ${tensor.data.length} != ${elements * 4}`);

    const values = floatView(tensor.data, elements);
    let sum = 0;
    let sumSq = 0;
    let finite = true;
    let maxAbs = 0;
    for (let i = 0; i < values.length; i++) {
      const v = values[i];
      if (!Number.isFinite(v)) { finite = false; nonFinite++; continue; }
      sum += v;
      sumSq += v * v;
      const abs = Math.abs(v);
      if (abs > maxAbs) maxAbs = abs;
    }
    const mean = sum / values.length;
    const variance = Math.max(0, sumSq / values.length - mean * mean);
    if (!finite) continue;
    if (/ln_(1|2|f)\.weight$/.test(name) && !(Math.abs(mean - 1) < 1e-3 && variance < 1e-6)) lnBad++;
    if (/\.bias$/.test(name) && maxAbs > 1e-6) biasBad++;
    if (/\.weight$/.test(name) && !/ln_/.test(name) && !(variance > 0)) degenerate++;
  }

  add('weights.shapes', 'Tensor shapes match configuration', shapeErrors.length === 0,
    shapeErrors.length ? shapeErrors.slice(0, 3).join('; ') : `${parsed.tensors.size} tensors verified`);
  add('weights.count', 'Tensor elements equal analytic parameter count', elementTotal === counts.total,
    `${elementTotal.toLocaleString()} vs ${counts.total.toLocaleString()}`);
  add('weights.count_match_model', 'Reported parameter count matches weights', elementTotal === project.parameters,
    `${project.parameters.toLocaleString()} parameters`);
  add('weights.finite', 'All weight values finite', nonFinite === 0, nonFinite ? `${nonFinite} non-finite values` : 'no NaN/Inf');
  add('weights.layernorm_init', 'LayerNorms initialised to identity', lnBad === 0, lnBad ? `${lnBad} layers off` : 'all at weight=1, bias=0');
  add('weights.bias_init', 'Bias tensors zero-initialised', biasBad === 0, biasBad ? `${biasBad} non-zero` : 'all zero');
  add('weights.nondegenerate', 'Linear weights are non-degenerate', degenerate === 0, degenerate ? `${degenerate} collapsed` : 'all have variance > 0');

  const expectedBytes = elementTotal * 4 + (weightsFile.content.length - elementTotal * 4 - (weightsFile.content.length - (elementTotal * 4 + headerSize(weightsFile.content))));
  add('weights.size', 'File size matches tensor payload', weightsFile.content.length === elementTotal * 4 + headerSize(weightsFile.content),
    `${weightsFile.content.length.toLocaleString()} bytes`);

  // --- tokenizer --------------------------------------------------------
  const vocabFile = project.files.find((f) => f.path === 'tokenizer/vocab.json');
  if (!vocabFile) {
    add('tokenizer.present', 'Tokenizer present', false, 'tokenizer/vocab.json missing');
  } else {
    let vocab;
    try {
      vocab = JSON.parse(vocabFile.content);
      add('tokenizer.parse', 'Tokenizer JSON parses', true, `${Object.keys(vocab.vocab).length} entries, ${vocab.merges.length} merges`);
    } catch (err) {
      add('tokenizer.parse', 'Tokenizer JSON parses', false, err.message);
    }
    if (vocab) {
      add('tokenizer.vocab_size', 'Vocabulary matches model embedding', vocab.vocab_size === cfg.vocab_size,
        `${vocab.vocab_size} == ${cfg.vocab_size}`);
      add('tokenizer.merges', 'BPE merges were learned', vocab.merges.length > 100, `${vocab.merges.length} merges`);
      add('tokenizer.algorithm', 'Tokenizer is byte-level (lossless by construction)',
        vocab.algorithm === 'byte-level-bpe' && vocab.vocab_size >= 512,
        `${vocab.algorithm}, ${vocab.vocab_size} tokens`);
      try {
        const enc = corpus.makeEncoder(vocab);
        const sample = project.files.find((f) => f.path === 'data/corpus/val.jsonl');
        const probe = sample ? JSON.parse(sample.content.split('\n')[0]).text : 'map a level at 128 bpm';
        const ids = enc.encode(probe);
        const roundTrip = enc.decode(ids) === probe;
        add('tokenizer.roundtrip', 'Encode → decode is lossless', roundTrip,
          `${ids.length} tokens for ${probe.length} chars`);
        add('tokenizer.compression', 'BPE compresses the corpus', ids.length < probe.length,
          `${(probe.length / Math.max(1, ids.length)).toFixed(2)} chars/token`);
      } catch (err) {
        add('tokenizer.roundtrip', 'Encode → decode is lossless', false, err.message);
      }
    }
  }

  // --- project files ----------------------------------------------------
  const required = [
    'README.md', 'config.json', 'generation_config.json', 'model.py', 'train.py', 'inference.py',
    'validate.py', 'requirements.txt', 'weights/tensor_manifest.json', 'tokenizer/tokenizer.py',
    'data/corpus/train.jsonl', 'data/corpus/val.jsonl', '.github/workflows/validate.yml',
    '.github/workflows/model-check.yml', 'LICENSE',
  ];
  const paths = new Set(project.files.map((f) => f.path));
  const missingFiles = required.filter((p) => !paths.has(p));
  add('files.required', 'All required project files generated', missingFiles.length === 0,
    missingFiles.length ? `missing: ${missingFiles.join(', ')}` : `${project.files.length} files`);

  const placeholders = project.files.filter((f) => typeof f.content === 'string' && /\{\{[A-Z0-9_]+\}\}/.test(f.content));
  add('files.templates', 'No unresolved template placeholders', placeholders.length === 0,
    placeholders.length ? placeholders.map((f) => f.path).join(', ') : 'all templates resolved');

  const badJson = [];
  for (const file of project.files.filter((f) => f.path.endsWith('.json'))) {
    try { JSON.parse(file.content); } catch { badJson.push(file.path); }
  }
  add('files.json', 'All JSON artifacts are valid', badJson.length === 0, badJson.join(', ') || 'all parse');

  const badJsonl = [];
  for (const file of project.files.filter((f) => f.path.endsWith('.jsonl'))) {
    for (const line of file.content.split('\n')) {
      if (!line.trim()) continue;
      try { JSON.parse(line); } catch { badJsonl.push(file.path); break; }
    }
  }
  add('files.jsonl', 'All JSONL datasets are valid', badJsonl.length === 0, badJsonl.join(', ') || 'every line parses');

  // manifest cross-check
  const manifestFile = project.files.find((f) => f.path === 'weights/tensor_manifest.json');
  if (manifestFile) {
    const manifest = JSON.parse(manifestFile.content);
    add('manifest.consistent', 'Tensor manifest matches weights',
      manifest.total_parameters === elementTotal && manifest.tensor_count === parsed.tensors.size,
      `${manifest.tensor_count} tensors / ${manifest.total_parameters.toLocaleString()} params`);
  }

  // --- training config --------------------------------------------------
  const t = project.training;
  add('training.sane', 'Training hyper-parameters are valid',
    t.learning_rate > 0 && t.learning_rate < 1 && t.batch_size > 0 && t.seq_len === cfg.n_ctx && t.max_steps > 0,
    `lr=${t.learning_rate}, bs=${t.batch_size}, seq=${t.seq_len}, steps=${t.max_steps}`);
  add('training.optimizer', 'Optimizer + scheduler configured', Boolean(t.optimizer) && Boolean(t.scheduler),
    `${t.optimizer} / ${t.scheduler}`);

  return finish(project, checks, { elementTotal, tensorCount: parsed.tensors.size, weightsBytes: weightsFile.content.length });
}

function headerSize(buf) {
  return 8 + Number(buf.readBigUInt64LE(0));
}

function finish(project, checks, extra = {}) {
  const failures = checks.filter((c) => c.status === 'fail');
  return {
    status: failures.length ? 'fail' : 'pass',
    checks,
    failures: failures.map((f) => `${f.label}: ${f.detail}`),
    passed: checks.length - failures.length,
    total: checks.length,
    parameters: project.parameters,
    tensorCount: extra.tensorCount || 0,
    weightsBytes: extra.weightsBytes || 0,
    validatedAt: new Date().toISOString(),
  };
}

module.exports = { validateProject, expectedShapes };
